<div class="heading-row"><h1>{{ $title }}</h1></div>
@if(!$state['user'])<div class="empty"><h3>{{ $t('Le storie sono più belle insieme', 'Stories are better together') }}</h3><button class="button primary" data-action="dialog" data-kind="login">{{ $t('Accedi', 'Sign in') }}</button></div>@else
